import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"42、【益】 震下巽上","description":"周易尚氏学 - 42、【益】 震下巽上","frontmatter":{"title":"42、【益】 震下巽上","description":"周易尚氏学 - 42、【益】 震下巽上"},"headers":[],"relativePath":"zh/classics/shangshi/047.md","filePath":"zh/classics/shangshi/047.md"}'),h={name:"zh/classics/shangshi/047.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_42、【益】-震下巽上" tabindex="-1">42、【益】 震下巽上 <a class="header-anchor" href="#_42、【益】-震下巽上" aria-label="Permalink to “42、【益】 震下巽上”">​</a></h1><p>贞我悔彼。以彼之阳。下来益我。故曰益也。归藏曰诚。说文。诚和也。书召诰。其丕能诚于小民。注亦训诚为和。风雷同声相应。和之至也。是周易以阳爻上下言。故曰益。归藏合上下卦言曰诚也。利有攸往。谓五。五既中且正。传所谓中正有庆也。利涉大川谓初。坤大川。震为舟。初阳遇阴而通。故曰利涉。传所谓术道乃行也。</p><p>彖曰。益。损上益下。民说无疆。自上下下。其道大光。利有攸往。中正有庆。利涉大川。木道乃行。益动而巽。曰进无疆。天施地生。其益无方。凡益之道。与时偕行。</p><p>坤为民。震为乐。故曰民说。坤为广。故曰无疆。否四来居下卦之下。故曰自上下下。震为玄黄。故曰大光。利有攸往。中正有庆。谓五。利涉大川。木道乃行。谓初。震为舟故曰木。古刳木为舟。故谓舟为木。。涣曰乘木有功。中孚曰乘木舟虚。皆以木为舟。利涉大川。故曰木道乃行。言舟行水上。舟楫之利用溥也。此纯释利涉之义。坤为水。震为舟。故曰木曰行。程子不知本即为舟。改木为益。野文之害。至斯而极。阳自外来。故曰天施。震为生。坤为地。故曰地生。益者否之终。泰之始。太玄云。巳用则贱。当时则贵。艮为时。与时偕行者。言时而当益。不能不益也。</p><p>象曰。风雷益。君子以见喜则迁。有过则改。</p><p>乾力善。坤为过。乾来初。得值得民。是迁善也。乾来初成震。坤象灭。是改过也。故学易之君子法之。</p><p>初九。利用为大作。元吉元咎。</p><p>虞翻云。大作谓耕播未来之利。按虞书。平秩东作。注岁起于东。而始就耕。谓之东作。禹贡恒卫既从。大陆既作。注二水巳治。从其故道。大陆之地已可耕作。是作即耕也。震为春。为耕。至春民尽耕。故曰大作。阳遇阴故利。乾元通。故元吉无咎。</p><h3 id="象曰。元吉无咎。下不厚事也。" tabindex="-1">象曰。元吉无咎。下不厚事也。 <a class="header-anchor" href="#象曰。元吉无咎。下不厚事也。" aria-label="Permalink to “象曰。元吉无咎。下不厚事也。”">​</a></h3><p>震健而决躁。故左氏以为射。言其速也。厚余也。行速故无余事。坤为事。言初虽在下。往利无阻。事无积滞。仍利涉大川之意也。</p><p>六二。或益之十朋之龟。弗克违。永贞吉。王用亨于帝吉。</p><p>艮为龟为朋友。坤数十。故曰十朋之龟。二应在五。五又故以十朋之龟益二也。二得阳应。故曰弗克违。二当位。故永贞于二吉。震为帝。王谓五。震为祭祀。故曰享。王用享于帝吉者。言五应二。则二吉也。</p><h3 id="象曰。或益之。自外来也。" tabindex="-1">象曰。或益之。自外来也。 <a class="header-anchor" href="#象曰。或益之。自外来也。" aria-label="Permalink to “象曰。或益之。自外来也。”">​</a></h3><p>外谓九五。恐人疑为初。</p><p>六三。益之用凶事。无咎。有孚中行。告公用圭。</p><p>三居坤中。坤为凶。为事。益之用凶事。言上来益三。为五所阻。大畜初九所谓有厉也。故曰凶事。二三四阴爻皆承五。九云。中行无咎。泰二云。得尚于中行。中行谓五。有孚中行者。言三与二四。同孚于五也。震为言。故为告。为王故为圭。坤为众。故曰公。公共也。三震为诸侯。告公用圭者。言约同诸侯执圭。共往朝五也。圭者天子所锡子。今朝天子。故执以为信。旧解以凶事为凶丧。或为凶荒。则告之天子。告之友邦。而受其碑隧（左　）。告必将仪。或执壁。或用圭。如臧文仲以纪献工告曜（左上入左下米）于齐。岂知告公用圭。即申有孚中行之义。与上之凶事无涉。是皆以他经例易。不知易文。上下旬。不必相属也。</p><h3 id="象曰。益用凶事。固有之也。" tabindex="-1">象曰。益用凶事。固有之也。 <a class="header-anchor" href="#象曰。益用凶事。固有之也。" aria-label="Permalink to “象曰。益用凶事。固有之也。”">​</a></h3><p>言阴遇阴。阳遇阳。近而不相得故凶。乃易理当然之事。故曰固有。</p><p>六四。中行告公从。利用为依迁国。</p><p>中行谓五。震为告。坤为臣。为众。从谓顺五。告公从者。言下三阴宜共同承五也。坤为国。震动。故曰迁国。艮止故曰依。左传隐六年。我周之东迁。晋郑焉依。说文依椅也。利用为依迁国者。言坤国播迁。至五艮而止。依以建国也。阴从阳故利。巽为利也。</p><h3 id="象曰。告公从。以益志也。" tabindex="-1">象曰。告公从。以益志也。 <a class="header-anchor" href="#象曰。告公从。以益志也。" aria-label="Permalink to “象曰。告公从。以益志也。”">​</a></h3><p>坤为志。公从九五。阳益阴。故曰益志。自坤志象失传。遂令某爻变成坎。以求志象矣。</p><p>九五。有孚惠心。勿问元吉。有孚惠我德。</p><p>尔雅释言。惠顺也。坤为顺为心。有孚惠心。言五孚于下坤而顺我也。震为问。五震覆。故曰勿问。五位尊。故曰元吉。勿问元吉者。言五乘重阴而大吉也。乾为德。有孚惠我德。言下三阴皆承顺我而有军也。</p><h3 id="象曰。有孚惠心。勿问之矣。惠我德。大得志也。" tabindex="-1">象曰。有孚惠心。勿问之矣。惠我德。大得志也。 <a class="header-anchor" href="#象曰。有孚惠心。勿问之矣。惠我德。大得志也。" aria-label="Permalink to “象曰。有孚惠心。勿问之矣。惠我德。大得志也。”">​</a></h3><p>坤为志。阳为大。阳五下乘重阴。故曰大得志。管子度地。天下之人皆归其德而惠其义。注惠顺也。正说此也。</p><p>上九。莫益之。或系之。立心勿恒。凶。</p><p>上与五为敌。故曰莫益。言益三也。上应在三。然上若益三。则为五所忌。而或系之。五艮体。艮为手为系也。坤为心，上应在坤。下虚。处巽上。风陨。进退不果。故曰立心勿恒。凶。恒九三云。不恒其德。益上九与恒九三同为卖上。故亦曰勿恒。缘巽下挠。故义同也。</p><h3 id="象曰。莫益之。偏辞也。或系之。自外来也。" tabindex="-1">象曰。莫益之。偏辞也。或系之。自外来也。 <a class="header-anchor" href="#象曰。莫益之。偏辞也。或系之。自外来也。" aria-label="Permalink to “象曰。莫益之。偏辞也。或系之。自外来也。”">​</a></h3><p>恐其被系。戒以莫益。故曰偏辞。左传襄三年。君子谓奚举其偏而不尝。注偏属也。犹私也。外谓五。五为上敌。下系云。几易之情近而不相得则凶。或害之。故上欲应三。五或系之。五在外。言系之者仍在外也。同人九三曰敌刚。中孚六三云。得敌。子夏传。三与四为敌。是阳遇阳。阴遇阴。愈近而愈不相得。旧解自虞翻以来。皆不知此为周易根本定例。故说或系之。皆不知系上九者为何爻。而无不误矣。 按否泰者。天道之自然。为运会所必有。故以次于上经十卦之后。损益者人事之进退。为人为之所关。故以次于下经第十卦之后。十者数之终。终则变。变则否泰迭更。损益互见。此其义也。又损者泰之终。以见否泰虽属无道。而由否而奉。由泰而否。损之益之。推挽之权。则在人为。有定而无定也。此上下经天人之分。动静之别。非参育之圣人。固不能知其故也。故于上经之否泰。自为一卷。下经之损益。自为一卷。以见此四卦为全经之枢纽。与他卦绝不同也。</p>',30)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
